package com.alpharip.staffmod.cases.caseredactiontool; import java.util.*; public final class RedactionService {private final LinkedHashMap<String,RedactionDocument> docs=new LinkedHashMap<String,RedactionDocument>();public synchronized boolean add(RedactionDocument d){if(d==null||docs.containsKey(d.getId()))return false;docs.put(d.getId(),d);return true;}public synchronized boolean replace(RedactionDocument d){if(d==null||!docs.containsKey(d.getId()))return false;docs.put(d.getId(),d);return true;}public synchronized boolean remove(String id){return docs.remove(id)!=null;}public synchronized RedactionDocument get(String id){return docs.get(id);}public synchronized List<RedactionDocument> getDocuments(){return Collections.unmodifiableList(new ArrayList<RedactionDocument>(docs.values()));}public synchronized boolean replaceAll(List<RedactionDocument> v){docs.clear();if(v!=null)for(RedactionDocument d:v)if(d!=null&&!docs.containsKey(d.getId()))docs.put(d.getId(),d);return true;}}